mapper.select:


	SELECT ROW_NUMBER() OVER(ORDER BY

			 B.KEYWORD_TYPE ${sortOrder} 
			 B.SEARCH_PC + B.SEARCH_MOBILE ${sortOrder} 
			 B.SEARCH_PC ${sortOrder} 
			 B.SEARCH_MOBILE ${sortOrder} 
			 B.AVERAGE_ADV ${sortOrder} 
			 B.INSERT_DT DESC 


		) AS RSEQ,
			B.*
			FROM
			(
        WITH RECURSIVE CATEGORY_TREE AS (
    		SELECT CATEGORY_CODE
    		FROM TB_CATEGORY
   			WHERE CATEGORY_CODE = #{categoryCode}

    		UNION ALL

    		SELECT tc.CATEGORY_CODE
    		FROM TB_CATEGORY tc
    		INNER JOIN CATEGORY_TREE ct ON tc.PARENT_CODE = ct.CATEGORY_CODE
			)
			SELECT

		        tk.*,
		        (SEARCH_PC + SEARCH_MOBILE ) AS TOTAL_SEARCH,
		        (SELECT COMMON_CODE_NM FROM TB_COMMON_CODE_DETAIL tcd WHERE tcd.COMMON_CODE = tk.KEYWORD_TYPE AND tcd.COMMON_GROUP_CODE = 'KEYWORD_TYPE') AS KEYWORD_TYPE_NM

		        ,CASE 
		            WHEN tcs.KEYWORD_CODE IS NOT NULL THEN 'Y'
		            ELSE 'N'
		        END AS CHECK_SELECT

		    FROM TB_KEYWORD tk

		    LEFT JOIN TB_CHECKSELECT tcs
		        ON tk.KEYWORD_CODE = tcs.KEYWORD_CODE
		            AND tcs.USER_ID = #{userId}


		    WHERE tk.CATEGORY_CODE IN (SELECT CATEGORY_CODE FROM CATEGORY_TREE)
		    ) B


		        AND B.KEYWORD_TYPE = #{keywordType}



		        AND B.KEYWORD_NM LIKE CONCAT('%', #{keywordNm}, '%')



		        AND (B.SEARCH_PC + B.SEARCH_MOBILE) >= #{totalSearchMin}


		    	AND (B.SEARCH_PC + B.SEARCH_MOBILE) <= #{totalSearchMax}



		        AND B.SEARCH_PC >= #{pcSearchMin}


		        AND B.SEARCH_PC <= #{pcSearchMax}


		        AND B.SEARCH_MOBILE >= #{mobileSearchMin}


		        AND B.SEARCH_MOBILE <= #{mobileSearchMax}


		        AND B.AVERAGE_ADV >= #{averageAdvMin}


		        AND B.AVERAGE_ADV <= #{averageAdvMax}


		        AND B.CHECK_SELECT  = #{checkSelect, jdbcType=VARCHAR}

SELECT COUNT(*) > 0
FROM TB_CHECKSELECT
WHERE USER_ID = #{userId}
  AND KEYWORD_CODE = #{keywordCode}

mapper.delete:
DELETE FROM TB_CHECKSELECT
WHERE USER_ID = #{userId}
  AND KEYWORD_CODE = #{keywordCode}

mapper.select:


	SELECT ROW_NUMBER() OVER(ORDER BY

			 B.KEYWORD_TYPE ${sortOrder} 
			 B.SEARCH_PC + B.SEARCH_MOBILE ${sortOrder} 
			 B.SEARCH_PC ${sortOrder} 
			 B.SEARCH_MOBILE ${sortOrder} 
			 B.AVERAGE_ADV ${sortOrder} 
			 B.INSERT_DT DESC 


		) AS RSEQ,
			B.*
			FROM
			(
        WITH RECURSIVE CATEGORY_TREE AS (
    		SELECT CATEGORY_CODE
    		FROM TB_CATEGORY
   			WHERE CATEGORY_CODE = #{categoryCode}

    		UNION ALL

    		SELECT tc.CATEGORY_CODE
    		FROM TB_CATEGORY tc
    		INNER JOIN CATEGORY_TREE ct ON tc.PARENT_CODE = ct.CATEGORY_CODE
			)
			SELECT
		        tk.KEYWORD_CODE,
				tk.KEYWORD_NM,
				tk.KEYWORD_TYPE,
				tk.SEARCH_PC,
				tk.SEARCH_MOBILE,
				tk.AVERAGE_ADV,
				tk.INSERT_DT,
		        (SEARCH_PC + SEARCH_MOBILE ) AS TOTAL_SEARCH,
		        (SELECT COMMON_CODE_NM FROM TB_COMMON_CODE_DETAIL tcd WHERE tcd.COMMON_CODE = tk.KEYWORD_TYPE AND tcd.COMMON_GROUP_CODE = 'KEYWORD_TYPE') AS KEYWORD_TYPE_NM

	            	, CASE WHEN tcs.KEYWORD_CODE IS NOT NULL THEN 'Y' ELSE 'N' END AS CHECK_SELECT

		    FROM TB_KEYWORD tk

		        LEFT JOIN TB_CHECKSELECT tcs ON tk.KEYWORD_CODE = tcs.KEYWORD_CODE AND tcs.USER_ID = #{userId}

		    WHERE tk.CATEGORY_CODE IN (SELECT CATEGORY_CODE FROM CATEGORY_TREE)
		    ) B


		        AND B.KEYWORD_TYPE = #{keywordType}



		        AND B.KEYWORD_NM LIKE CONCAT('%', #{keywordNm}, '%')



		        AND (B.SEARCH_PC + B.SEARCH_MOBILE) >= #{totalSearchMin}


		    	AND (B.SEARCH_PC + B.SEARCH_MOBILE) <= #{totalSearchMax}



		        AND B.SEARCH_PC >= #{pcSearchMin}


		        AND B.SEARCH_PC <= #{pcSearchMax}


		        AND B.SEARCH_MOBILE >= #{mobileSearchMin}


		        AND B.SEARCH_MOBILE <= #{mobileSearchMax}


		        AND B.AVERAGE_ADV >= #{averageAdvMin}


		        AND B.AVERAGE_ADV <= #{averageAdvMax}


		        AND B.CHECK_SELECT  = #{checkSelect, jdbcType=VARCHAR}
